  function exportRecommendationHistoryCsv(){
    if(!currentRecommendationHistory.length)return;
    const headers=['Recorded At','Symbol','Market','Horizon','Decision','AI Recommendation','Technical Score','Entry Price','AI Target','AI Stop-loss','Current Price','Return Since Call %','Status'];
    const rows=currentRecommendationHistory.map(r=>[r.created_at,r.symbol,r.market,r.horizon,r.recommendation,r.ai_recommendation,r.technical_score,r.entry_price,r.ai_target,r.ai_stop_loss,r.current_price,r.return_since_call_pct,r.status]);
    const symbol=String($('stock-symbol').dataset.symbol||'stock').replace(/[^a-z0-9._-]+/gi,'-'),market=String($('stock-symbol').dataset.market||'market').replace(/[^a-z0-9._-]+/gi,'-');
    downloadCsv(`${symbol}-${market}-ai-decision-track-record.csv`,headers,rows);
  }

  async function importRecommendationHistoryCsv(event){
    const input=event.target,file=input.files?.[0];if(!file)return;const button=$('recommendation-import');button.disabled=true;setImportStatus('recommendation-import-status',`Importing ${file.name}…`);
    try{
      const rows=parseCsv(await file.text());
      if(rows.length>500)throw new Error('A maximum of 500 AI decision records can be imported at once.');
      const items=rows.map(row=>{const rawDate=row.recorded_at||row.created_at||'',date=rawDate?new Date(rawDate):null,ai=String(row.ai_recommendation||'').trim().toUpperCase(),score=csvNumber(row.technical_score),entry=csvNumber(row.entry_price),target=csvNumber(row.ai_target),stop=csvNumber(row.ai_stop_loss);return {created_at:date&&!Number.isNaN(date.getTime())?date.toISOString():null,symbol:String(row.symbol||'').trim().toUpperCase(),market:String(row.market||'').trim().toUpperCase(),horizon:String(row.horizon||'').trim().toUpperCase(),recommendation:String(row.decision||row.recommendation||'').trim().toUpperCase(),ai_recommendation:['BUY','HOLD','SELL'].includes(ai)?ai:null,technical_score:score!=null&&score>=0&&score<=100?score:null,entry_price:entry!=null&&entry>0?entry:null,ai_target:target!=null&&target>0?target:null,ai_stop_loss:stop!=null&&stop>0?stop:null};}).filter(item=>item.symbol&&['IN','US'].includes(item.market)&&['1D','1W','1M','3M','6M','1Y'].includes(item.horizon)&&['BUY','HOLD','SELL'].includes(item.recommendation));
      if(!items.length)throw new Error('No valid records found. Use a CSV exported from this section.');
      const res=await fetch('/recommendations/import',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({items})});const data=await res.json();if(!res.ok)throw new Error(data.detail||'Import failed');
      setImportStatus('recommendation-import-status',`Imported ${data.imported??0} record(s); skipped ${data.skipped??0} duplicate(s).`,'success');
      const symbol=$('stock-symbol').dataset.symbol,market=$('stock-symbol').dataset.market;if(symbol)await loadRecommendationHistory(symbol,market);
    }catch(err){setImportStatus('recommendation-import-status',err.message||'Could not import this CSV.','error');}finally{button.disabled=false;input.value='';}
  }

