  async function searchFunds(q){const market=$('mf-market-select').value,res=await fetch(`/mf/search?q=${encodeURIComponent(q)}&market=${market}&limit=20`);if(!res.ok)return;const rows=await res.json();$('mf-autocomplete').innerHTML=rows.slice(0,15).map(x=>`<div class="ac-item" data-id="${escapeHtml(x.identifier||x.scheme_code||x.symbol)}" data-name="${escapeHtml(x.scheme_name||x.symbol)}">${escapeHtml(x.scheme_name||x.symbol)} <small>${escapeHtml(x.quote_type||'')}</small></div>`).join('');$('mf-autocomplete').classList.toggle('hidden',!rows.length);$('mf-autocomplete').querySelectorAll('.ac-item').forEach(el=>el.addEventListener('click',()=>{$('mf-search-input').value=el.dataset.name||el.textContent.trim();$('mf-autocomplete').classList.add('hidden');analyzeFund(el.dataset.id,market);}));}
