      $('screen-body').innerHTML=rows.map(r=>`<tr class="clickable-row" role="button" tabindex="0" data-asset="FUND" data-market="${escapeHtml(r.market||d.market)}" data-id="${escapeHtml(r.identifier)}" data-name="${escapeHtml(r.name||r.identifier)}" title="Open full fund analysis"><td><b>${escapeHtml(r.name||r.identifier)}</b><br><small>${escapeHtml(r.identifier)}</small></td><td>${r.score}</td><td>${pct(r.return_1d_pct)}</td><td>${pct(r.return_1y_pct)}</td><td>${pct(r.return_3y_annualized_pct)}</td><td>${num(r.sharpe_ratio)}</td><td>${pct(r.alpha_vs_benchmark_pct)}</td><td>${pct(r.max_drawdown_pct)}</td><td>${r.expense_ratio_pct==null?'--':`${num(r.expense_ratio_pct)}%`}</td><td>${escapeHtml(r.rating)}</td></tr>`).join('');
