  function renderPaperJournal(){const rows=getPaper();$('paper-journal').innerHTML=rows.length?`<table class="data-table"><thead><tr><th>Date</th><th>Market</th><th>Symbol</th><th>Action</th><th>Entry</th><th>Target</th><th>Risk</th><th></th></tr></thead><tbody>${rows.map((x,i)=>`<tr><td>${escapeHtml(newsDate(x.created_at))}</td><td>${escapeHtml(x.market)}</td><td><b>${escapeHtml(x.symbol)}</b></td><td>${escapeHtml(x.action)}</td><td>${num(x.entry)}</td><td>${num(x.target)}</td><td>${num(x.stop)}</td><td><button class="icon-btn paper-remove" data-i="${i}"><i class="fa-solid fa-trash"></i></button></td></tr>`).join('')}</tbody></table>`:'<p class="text-muted text-sm">No paper ideas yet. This journal stays in this browser only.</p>';$('paper-journal').querySelectorAll('.paper-remove').forEach(b=>b.addEventListener('click',()=>{const a=getPaper();a.splice(Number(b.dataset.i),1);savePaper(a);renderPaperJournal();}));}
