  const watchKey='stock-ai-v6-watchlist';const getWatch=()=>{try{return JSON.parse(localStorage.getItem(watchKey)||'[]')}catch{return[]}};const saveWatch=x=>localStorage.setItem(watchKey,JSON.stringify(x));
